static uint16_t bswap_16(uint16_t x)
{
    return x << 8 | x >> 8;
}

static uint32_t bswap_32(uint32_t x)
{
    return x >> 24 | (x >> 8 & 0xff00) | (x << 8 & 0xff0000) | x << 24;
}

static uint16_t chk_htons(uint16_t n)
{
    union { int i; char c; } u = { 1 };
    return u.c ? bswap_16(n) : n;
}

static uint32_t chk_htonl(uint32_t n)
{
    union { int i; char c; } u = { 1 };
    return u.c ? bswap_32(n) : n;
}

static unsigned short checksum(unsigned short *addr, int count)
{
    long sum = 0;

    while (count > 1) {
        sum += *(unsigned short*)addr++;
        count -= 2;
    }

    if (count > 0) {
        char left_over[2] = { 0 };
        left_over[0] = *addr;
        sum += *(unsigned short*)left_over;
    }
    while (sum >> 16)
        sum = (sum & 0xffff) + (sum >> 16);
    return ~sum;
}

static void ip6_addr_adapt(struct IP6_ADDR_T *p_src, struct IP6_ADDR_T *p_dest, uint32_t *src, uint32_t *dst)
{
    uint32_t addr_src =0;
    uint32_t addr_dst = 0;
    uint32_t tmp_src = 0;
    uint32_t tmp_dst = 0;
    for (uint8_t addr_part = 0; addr_part < 4; addr_part++) {
        addr_src = p_src->addr[addr_part];
        tmp_src = (uint32_t)(tmp_src + (addr_src & 0xffffUL));
        tmp_src = (uint32_t)(tmp_src + ((addr_src >> 16) & 0xffffUL));
        addr_dst = p_dest->addr[addr_part];
        tmp_dst = (uint32_t)(tmp_dst + (addr_dst & 0xffffUL));
        tmp_dst = (uint32_t)(tmp_dst + ((addr_dst >> 16) & 0xffffUL));
    }

    tmp_src = FOLD_U32T(tmp_src);
    tmp_src = FOLD_U32T(tmp_src);
    tmp_dst = FOLD_U32T(tmp_dst);
    tmp_dst = FOLD_U32T(tmp_dst);
    *src = tmp_src;
    *dst = tmp_dst;
}

static void tcp_hdr_adapt(struct TCP_HEADER_INFO_T *tcp_hdr_info, uint8_t *addr)
{
    uint32_t ip6_src;
    uint32_t ip6_dst;
    uint8_t version;

    version = ((*(uint8_t *)addr) >> 4) & 0xff;
    if (version == IPV4) {
        tcp_hdr_info->len = chk_htons(*((uint16_t *)&addr[2])) - 20;
        tcp_hdr_info->data = &addr[20];
        tcp_hdr_info->saddr = chk_htonl(*((uint32_t *)&addr[12]));
        tcp_hdr_info->daddr = chk_htonl(*((uint32_t *)&addr[16]));
    } else if (version == IPV6) {
        ip6_addr_adapt((struct IP6_ADDR_T*)(&addr[8]), (struct IP6_ADDR_T*)(&addr[24]), &ip6_src, &ip6_dst);
        tcp_hdr_info->len = chk_htons(*((uint16_t *)&addr[4]));
        tcp_hdr_info->data = &addr[40];
        tcp_hdr_info->saddr = chk_htons(ip6_src);
        tcp_hdr_info->daddr = chk_htons(ip6_dst);
    }
    tcp_hdr_info->proto = 0x06;
}

