{
    uint8_t *data;
    uint32_t len;
    uint16_t res;
    struct PSD_HEADER_T tcp_psd_header;
    struct TCP_HEADER_INFO_T tcp_hdr_info;

    memset(&tcp_hdr_info, 0, sizeof(tcp_hdr_info));
    tcp_hdr_adapt(&tcp_hdr_info, addr);

    tcp_psd_header.saddr = chk_htonl(tcp_hdr_info.saddr);
    tcp_psd_header.daddr = chk_htonl(tcp_hdr_info.daddr);
    tcp_psd_header.mbz = 0;
    tcp_psd_header.ptcl = tcp_hdr_info.proto;
    tcp_psd_header.tcpl = tcp_hdr_info.len;
    len = sizeof(tcp_psd_header) + tcp_psd_header.tcpl;
    data = tcp_data;
    memcpy(data, &tcp_psd_header, sizeof(uint32_t));
    memcpy(&(data[4]), &tcp_psd_header.daddr, sizeof(uint32_t));
    data[8] = 0;
    data[9] = (uint16_t)tcp_psd_header.ptcl;
    data[10] = (uint16_t)(tcp_psd_header.tcpl & 0xFF00) >> 8;
    data[11] = (uint16_t)(tcp_psd_header.tcpl & 0x00FF);
    memcpy(&data[sizeof(tcp_psd_header)], (uint8_t*)tcp_hdr_info.data, tcp_psd_header.tcpl);
    res =  checksum((uint16_t *)data, len);

    return res;
}

static uint16_t checksum_ip(uint8_t *addr) {
    uint16_t res;
    res = checksum((uint16_t *)addr, 20);
    return res;
}

static void checksum_cb(const uint16_t res, uint32_t error)
{
    if (error)
        ASSERT(false, "checksum irq error: error_state=%#x\n", res);
    TRACE(0, "cb checksum result = %#x\n", res);
}

void checksum_test(void)
{
    uint32_t ret;
    uint16_t res;
    uint8_t  *pkt[] = {ip_pkt0, ip_pkt1, ip_pkt2, ip_pkt3, ip_pkt4, ip_pkt5, ip_pkt6};
    TRACE(0, "checksum test begin\n");
    hal_checksum_open();

    /*ip checksum*/
    for (int i = 0;i < 2;i++) {
        ASSERT(checksum_ip(pkt[i]) == checksum_res[i], "soft ip checksum error!!!index = %d\n", i);

        ret = hal_checksum_ip_start(pkt[i], &res, checksum_cb);
        if (ret == -1) {
            TRACE(0, "NON BLOCK ERR_IN_UES,index = %d\n", i);
        }
        hal_sys_timer_delay_us(1000);
        ret = hal_checksum_ip_start(pkt[i], &res, NULL);
        if (ret == -1) {
            TRACE(0, "BLOCK ERR_IN_UES,index = %d\n", i);
        } else {
            ASSERT(res == checksum_res[i], "hw ip checksum error!!!index = %d\n", i);
        }
    }
    /*tcp checksum*/
    for(int i = 0;i < 7;i++) {
        ASSERT(checksum_tcp(pkt[i]) == checksum_res[i+2], "soft tcp checksum error!!!index = %d\n", i+2);

        ret = hal_checksum_tcp_start(pkt[i], &res, checksum_cb);
        if (ret == -1) {
            TRACE(0, "NON BLOCK ERR_IN_UES,index = %d\n", i+2);
        }
        hal_sys_timer_delay_us(1000);

        ret = hal_checksum_tcp_start(pkt[i], &res, NULL);
        if (ret == -1) {
            TRACE(0, "BLOCK ERR_IN_UES,index = %d\n", i+2);
        } else {
            ASSERT(res == checksum_res[i+2], "hw tcp checksum error!!!index = %d\n", i+2);
        }
    }
    TRACE(0, "checksum test success!!!\n");
}

#endif
